/* ---------------- PRODUCT ---------------- */
T('audience-and-positioning',{ d:'product', t:'Audience, positioning and differentiation', tag:'Why yours, instead of the thousand others? Answer in one sentence or you do not know yet.',
  what:`The market-facing statement of the player and the promise: who the game is for, what it does that the alternatives do not, and how a stranger would recognize that in ten seconds. Positioning is the fantasy plus the differentiator, stated for someone who has not played.`,
  why:[`Discovery is the main failure mode of finished games. A game nobody can describe is a game nobody recommends.`,`Positioning is the scope filter seen from outside: features that do not sharpen the sentence dilute the product.`,`A differentiator that is invisible in the first ten seconds of a trailer or the first ten minutes of play does not exist for the market.`],
  think:{ q:[`Complete: "For [PLAYER] who [WANTS], this is the game that [DIFFERENTIATOR], unlike [ALTERNATIVES]."`,`Is the differentiator visible in a screenshot? A trailer? The first ten minutes?`,`Which existing games will I be compared to? What do their players complain about?`,`Is the differentiator a feature or an experience? Experiences travel further by word of mouth.`],
    trade:[`Sharp positioning attracts a niche strongly and excludes the rest.`,`Genre-standard positioning is safe to explain and easy to ignore.`],
    traps:[`"It is X meets Y" where the meeting point is not the experience.`,`Differentiating on features the player only meets after ten hours.`,`Positioning written by marketing after the design is fixed.`],
    good:[`Playtesters describe the game the way the positioning does, without seeing it.`,`Strangers ask the right question after seeing one screenshot.`],
    bad:[`Every description starts with the genre and ends with a feature list.`] },
  how:[`Write the positioning sentence. Test it on strangers: what do they expect? Compare with the game.`,`Check the differentiator is in the first ten minutes of play and in one screenshot.`,`Mine the complaints about comparable games for a differentiator players already want.`,`Use the sentence as a gate: features that do not sharpen it wait.`],
  ai:{ yes:[`Generate positioning candidates from the fantasy and comparable games.`,`Mine reviews of comparables for unmet wants.`,`Check a feature list against the positioning and flag dilution.`],
       no:[`Choose the positioning. It is strategy.`,`Estimate market size with confidence it does not have.`] },
  prompts:[{l:'Positioning stress test',p:`Our positioning is: "[SENTENCE]". Comparable games: [LIST]. Act as a skeptical publisher. Is the differentiator visible in a screenshot and in the first 10 minutes of the described flow ([FLOW])? Which comparable already delivers it? What would a player of each comparable say when they hear the sentence? Propose 3 sharper alternatives grounded in what players of the comparables complain about, and state what each alternative would force us to cut.`}],
  verify:[`Did it flatter the positioning or test it?`,`Are the complaints it cites real and sourced, or plausible inventions?`],
  test:[`Show strangers one screenshot and the sentence. Ask what they expect. Compare.`,`After a first session, ask testers to describe the game to a friend. Compare with the sentence.`],
  rel:[['who-is-the-player','Positioning is the player model for the market.'],['core-experience','The promise must match the experience.'],['platform-and-session','Where and how long they play is part of who they are.'],['scope-control','Positioning is the external scope filter.'],['business-model','Model and positioning must agree.']] });

T('platform-and-session',{ d:'product', t:'Platform, session length and context', tag:'Where and for how long decides pacing, input, readability and save design before you draw a level.',
  what:`The physical and temporal frame of play: device, input method, screen size and distance, typical session length, interruption pattern, and whether play is continuous or in bursts. These are design constraints, not afterthoughts.`,
  why:[`A loop that needs 20 minutes to become interesting fails on a platform where sessions are 5.`,`Input precision decides which skills you can demand.`,`Screen size and distance decide how much information the player can read.`],
  think:{ q:[`What is the median session? What must be satisfying inside it?`,`How does a session end: at a natural stopping point, or by interruption? Does the game survive interruption?`,`What can the player see and press on this device, in this posture?`,`Which platform conventions does the player expect? Which will I break, and why?`],
    trade:[`Designing for the smallest session includes more contexts and caps depth per session.`,`Multi-platform reach widens the audience and forces lowest-common-denominator input and readability.`],
    traps:[`Testing on a monitor, shipping on a phone.`,`Sessions that only end at boss fights.`,`Save systems designed after the levels.`],
    good:[`Players finish a satisfying unit inside a typical session.`,`Players quit at natural points and resume without friction.`],
    bad:[`Players lose progress to interruptions or say "I never have time to get anywhere".`] },
  how:[`Write the session profile: median length, interruption pattern, device, posture.`,`Define the satisfying unit that fits inside the median session. Structure the game around it.`,`Design saving and resuming as core features.`,`Test on the target device, in the target posture, with realistic interruptions.`],
  ai:{ yes:[`Audit a level and progression plan against the session profile.`,`Propose session-unit structures for a given loop and length.`,`Check readability and input demands against device constraints.`],
       no:[`Choose the platform. That is strategy.`] },
  prompts:[{l:'Session fit audit',p:`Session profile: median [MINUTES], interruptions every [MINUTES], device [DEVICE], posture [POSTURE]. Here is our level and progression plan: [PLAN]. Identify the satisfying unit that fits inside a median session, or state that none does. Flag stretches that cannot be interrupted safely and skills that exceed the input precision of the device. Propose the smallest restructuring that gives every session a complete unit.`}],
  verify:[`Did it account for the actual device constraints, or assume a desktop?`],
  test:[`Log real session lengths and end reasons.`,`Test with interruptions: what is lost?`,`Test on device and at distance.`],
  rel:[['goals-horizons','The session goal must fit the session.'],['readability-and-hierarchy','Screen and distance set readability.'],['controls-and-friction','Input method sets skill demands.'],['return-and-quit','Interrupted sessions are a churn source.']] });

T('business-model',{ d:'product', t:'Business model and monetization', tag:'The model should pay for the fun without becoming the design. Where they conflict, players notice first.',
  what:`How the game earns: premium, free-to-play with purchases, subscription, ads, DLC, live service. Each model applies pressure to the design economy, progression, session design and social systems. Ethical monetization sells things players value without manufacturing the pain it relieves.`,
  why:[`Monetization pressure is the most common corrupter of design: timers to sell skips, grind to sell boosts, gacha to sell hope.`,`Players sense when a system exists to sell rather than to play, and it poisons trust in adjacent systems.`,`The model decides what "retention" means and which metrics the team will be pushed to optimize.`],
  think:{ q:[`What does the player pay for, and would they value it if the game had no store?`,`Which design decisions exist only because of the model? Would the game be better without them?`,`What pain does a purchase relieve, and did the design create that pain on purpose?`,`Which metric will the model push us to optimize, and does that metric align with fun?`],
    trade:[`Premium aligns incentives with fun and limits reach and revenue tail.`,`Free-to-play widens reach and creates constant pressure to monetize friction.`],
    traps:[`Designing the store before the loop.`,`Metrics (ARPU, session count) optimized at the cost of the experience.`,`"Ethical" monetization declared rather than tested with players.`],
    good:[`Players describe purchases as wanted, not needed.`,`Non-payers describe the game as complete.`],
    bad:[`Players describe the game as "pay to win" or "designed to annoy you into paying".`] },
  how:[`List every system that exists for the model. For each, ask whether the game would be better without it.`,`Ensure the loop is voluntarily replayed before any monetization is added.`,`Sell value (expression, convenience players did not need to be annoyed into wanting, content) rather than relief.`,`Test with payers and non-payers. Ask both what the store feels like.`],
  ai:{ yes:[`Model revenue under different structures and player behavior assumptions.`,`Audit the design for monetization-induced friction.`,`Summarize regulatory and platform policy constraints (as a starting point. Verify with counsel).`],
       no:[`Decide monetization ethics. That is a values decision.`,`Optimize a metric without you deciding whether the metric is right.`] },
  prompts:[{l:'Monetization friction audit',p:`Here are our systems and our business model: [SYSTEMS, MODEL]. Identify every system or number that exists primarily to create a purchase opportunity. For each, describe the player pain it creates, whether the design manufactured that pain, and what the game would feel like without the system. Then propose monetization that sells value players would want in a game with no store, given the fantasy "[FANTASY]".`}],
  verify:[`Did it defend friction as "industry standard"?`,`Did it distinguish value from relief?`],
  test:[`Ask non-payers whether the game feels complete.`,`Ask payers why they bought. "Wanted" versus "had to".`,`Where do players mention the store unprompted, and in what tone?`],
  rel:[['economy-and-resources','The model pressures the design economy.'],['progression','Grind is where monetization pressure shows.'],['social-experience','Social systems and spending interact.'],['audience-and-positioning','Model and positioning must agree.']] });

T('scope-control',{ d:'product', t:'Scope control', tag:'Scope should follow validated value, not imagination. AI makes this harder, not easier.',
  what:`The discipline of deciding what the game contains, based on what has been shown to work rather than what could be built. The healthy sequence is idea, prototype, evidence, commit. The unhealthy one is idea, production commitment. AI makes implementation cheap enough that huge amounts of mediocre content can be produced before anyone asks whether the core is fun.`,
  why:[`Scope is the most common cause of games that never ship or ship hollow.`,`Cheap implementation removes the natural brake on scope. The brake must become deliberate.`,`Every feature carries costs beyond building it: teaching, balancing, maintaining, and diluting the core.`],
  think:{ q:[`What has been validated with players? Scope grows from there, not from the pitch.`,`What is the smallest version of this game that delivers the core experience?`,`For each feature: what would we lose by not building it? Be specific about the player experience.`,`What is on the "not this game" list? Is it written down?`],
    trade:[`Tight scope ships and may feel thin. Wide scope feels ambitious and may never cohere.`,`Cutting late saves the project and wastes the cut work.`],
    traps:[`Scope defined by the pitch deck.`,`"AI can build it in a day" as an argument to build it.`,`Content pipelines started before the system is validated.`,`Never writing the not-list.`],
    good:[`The team can name the three things the game is about and the ten it is not.`,`Cut features have a documented reason and a player-evidence trigger for revisiting.`],
    bad:[`Feature list grows every sprint. Core loop metrics do not move.`] },
  how:[`Write the core experience statement and the not-list.`,`Order features by dependency on validated evidence: what needs the loop proven first, what needs progression proven, and so on.`,`Gate each production commitment on a prototype and playtest result.`,`Review the feature list monthly: what has evidence, what is imagination?`,`Treat cheap AI implementation as a reason to prototype more, not to ship more.`],
  ai:{ yes:[`Map feature dependencies and identify what can be validated first.`,`Estimate total cost including teaching, balance and maintenance, not just build.`,`Draft the not-list from the positioning and flag features that violate it.`],
       no:[`Decide what to cut. That is the human's most important job.`,`Argue that low build cost justifies building.`] },
  prompts:[{l:'Scope triage',p:`Here is our feature list and what has been validated with players so far: [FEATURES, EVIDENCE]. For each feature, state which validated result it depends on, its full cost (build, teach, balance, maintain, dilution of core), and what the player would lose without it. Sort into: build now (evidence supports), prototype first (evidence missing), defer (depends on unvalidated features), and cut (does not serve "[CORE EXPERIENCE]"). Argue against your own "build now" list once.`}],
  verify:[`Did it count build cost only?`,`Did it defer decisions to "it depends" instead of sorting?`],
  test:[`Does removing a feature in a prototype change player behavior? If not, it may not need to exist.`,`Which features do players never mention or use?`],
  rel:[['prototyping','Prototypes are how scope earns its place.'],['content-multiplies','Content is where scope explodes.'],['core-experience','The experience statement is the scope filter.'],['ai-failure-modes','Feature inflation and content spam are AI-era scope failures.'],['should-we-build-this','The decision tree operationalizes scope control.']] });

/* ---------------- PRODUCTION ---------------- */
T('prototyping',{ d:'production', t:'Prototyping: the cheapest possible test', tag:'A prototype answers one question. If it answers none, it is a demo.',
  what:`A deliberately incomplete build made to test one hypothesis: paper, grey boxes, spreadsheets, a single mechanic in a blank room. The value of a prototype is the question it answers and the speed at which it answers it. Fidelity is a cost, not a virtue.`,
  why:[`The riskiest assumptions are cheapest to test before anything is built on them.`,`Most design ideas are wrong in a way that only playing reveals. Prototypes find out early.`,`AI makes prototypes nearly free, which means the limiting factor is how well you frame the question.`],
  think:{ q:[`What is the one question this prototype answers? What result would kill the idea?`,`What is the least I can build to get that answer? Paper? A spreadsheet? Ten minutes of grey boxes?`,`Who needs to play it: me, the team, or target players?`,`What will I measure, and what would a positive result look like?`],
    trade:[`Low fidelity is fast and can hide problems that only appear with feel.`,`Higher fidelity finds feel problems and invites premature attachment.`],
    traps:[`Prototypes that grow into the game.`,`Prototyping the safe parts because they are easy.`,`Testing a prototype only with the team.`,`No kill criterion, so every result is "promising".`],
    good:[`Prototypes are thrown away. Findings are kept.`,`Each prototype has a written hypothesis and result.`],
    bad:[`The prototype has a save system.`] },
  how:[`Write the hypothesis and the kill criterion before building anything.`,`Choose the cheapest medium that can answer the question.`,`Build in a day or less if possible. Use AI aggressively for the build.`,`Test with the right players. Record the result and the decision.`,`Throw it away, or explicitly promote it with a new plan.`],
  ai:{ yes:[`Build prototypes fast, with exposed tuning and logging.`,`Propose the cheapest medium for a given question.`,`Generate variants of a prototype to compare.`,`Write the analysis script for the logs.`],
       no:[`Decide the prototype "works". Players decide.`,`Add polish or scope to the prototype unasked.`] },
  prompts:[{l:'Prototype spec',p:`Hypothesis: we believe [PLAYER] will [BEHAVIOR] because [REASON]. We will know it is working when [SIGNAL], and we will kill the idea if [KILL CRITERION]. Propose the cheapest prototype that tests this (paper, spreadsheet, or minimal build), the tuning values to expose, the events to log, and a 15-minute test protocol for [N] players. Then build it in [ENGINE/HTML] with no menus, no art beyond shapes, and a log export.`}],
  verify:[`Does the prototype isolate the hypothesis, or bundle features?`,`Did it add anything not needed to answer the question?`],
  test:[`Run the protocol. Did the signal appear? Did the kill criterion trigger?`,`Did players do anything unexpected? Record it.`,`Decide: keep, change, simplify, kill. Write it down.`],
  rel:[['hypothesis-driven-design','The hypothesis is the prototype spec.'],['core-loop','The loop is the first prototype.'],['playtesting','Prototypes exist to be tested.'],['ai-for-implementation','AI builds prototypes.'],['scope-control','Prototypes are how scope earns its place.']] });

T('hypothesis-driven-design',{ d:'production', t:'Hypothesis-driven design', tag:'We believe [player] will [behavior] because [reason]. We will know when [signal]. Write it before you build.',
  what:`Expressing every significant design decision as a testable claim about player behavior, with an observable signal and a kill criterion, before building. The template comes from Lean Startup and Lean UX. Its game analogue is Valve's practice (Mike Ambinder) of treating designs as hypotheses and playtests as experiments. The workflow is hypothesis, prototype, test, evidence, decision, versus idea, big build, polish, hope.`,
  why:[`Writing the hypothesis first prevents rationalizing the result afterwards.`,`It forces the question "what would I observe?" which converts taste into something testable without removing taste from the decision.`,`It makes AI useful: a hypothesis is a precise brief for a prototype, a test protocol and an analysis.`],
  think:{ q:[`Who exactly will do what, and why do I think so?`,`What would I see a player do if this is true? If it is false?`,`What is the smallest experiment that distinguishes true from false?`,`What result would make me stop? If none, I am not testing. I am hoping.`],
    trade:[`Rigor slows the first iteration and speeds every one after.`,`Observable signals favor measurable behavior over subtle feeling. Guard against ignoring what you cannot count.`],
    traps:[`Hypotheses about the game ("combat will be deep") instead of the player ("players will switch weapons by enemy type").`,`Signals that cannot be observed in a playtest.`,`Treating a confirmed hypothesis as proof rather than as evidence.`],
    good:[`Every prototype has a one-line hypothesis and a recorded result.`,`Design debates end with "let us test it" and a protocol.`],
    bad:[`Post-test discussions are about whether people "liked it".`] },
  how:[`Use the Playtest Hypothesis Builder: player, behavior, reason, signal, kill criterion.`,`Design the smallest prototype that could show the signal.`,`Run the test. Record what happened versus what was predicted.`,`Decide: keep, change, simplify, kill. Write the next hypothesis.`],
  ai:{ yes:[`Turn a vague idea into several testable hypotheses with signals.`,`Design test protocols and analysis for a hypothesis.`,`Challenge a hypothesis: what else would explain the predicted signal?`],
       no:[`Decide which hypothesis matters most. Prioritization is judgment.`,`Declare a hypothesis confirmed from reasoning alone.`] },
  prompts:[{l:'Hypothesis sharpening',p:`Here is a design idea: [IDEA]. Rewrite it as 3 distinct hypotheses in the form "We believe [PLAYER] will [BEHAVIOR] because [REASON]. We will know when [OBSERVABLE SIGNAL]." For each, state a kill criterion, the cheapest experiment, and an alternative explanation that would produce the same signal even if the hypothesis were false. Rank by how much the game depends on the hypothesis being true.`}],
  verify:[`Are the behaviors observable in a 15-minute session, or abstractions?`,`Did it provide alternative explanations, or assume the signal proves the claim?`],
  test:[`Did the predicted behavior occur? At what rate?`,`Did anything else explain it?`,`Would you have made the same decision without the hypothesis? If yes, it was too safe.`],
  rel:[['prototyping','The hypothesis specifies the prototype.'],['playtesting','The test is where evidence comes from.'],['iteration-and-evidence','Evidence feeds the decision.'],['ai-loop','Hypothesize is step 2 of the master loop.']] });

T('playtesting',{ d:'production', t:'Playtesting: the truth machine', tag:'What players say is useful. What players do is evidence. Neither means anything without context.',
  what:`Observing real players play, to learn what the game actually does rather than what it was meant to do. Methods: silent observation, think-aloud, task-based usability tests, interviews, surveys, telemetry, replay analysis. The designer's job during a test is to watch, not to defend or explain.`,
  why:[`The designer cannot see their own game. They know too much. Only new eyes reveal what is taught, what is legible and what is fun.`,`Behavior beats opinion: players say what they think you want, or what they think they felt, and both are unreliable. Behavior is what happened.`,`Cadence matters. A game tested weekly is a different game from one tested at milestones.`],
  think:{ q:[`What question does this test answer? What will I watch for?`,`Who is playing: target players, or whoever was available?`,`Where do players hesitate, repeat, drift, quit, experiment, talk?`,`Am I explaining? Stop.`,`What did they do that I did not expect? That is the most valuable finding.`],
    trade:[`Silent observation yields clean behavior and little insight into intent. Think-aloud yields intent and distorts behavior.`,`Telemetry scales and loses context. Observation has context and does not scale.`],
    traps:[`Explaining or helping during the test.`,`Asking "was it fun?" (always yes) instead of watching what they did.`,`Testing with the team or friends.`,`Reading one tester's opinion as a pattern.`,`Changing five things after one test.`],
    good:[`Tests are weekly, with a written question and a written result.`,`Findings surprise the team regularly.`],
    bad:[`Tests are demos. The designer talks more than the player.`] },
  how:[`Write the question and the hypothesis. Recruit players who match the model.`,`Silent observation first: no help, no explanation, take timestamped notes on hesitation, repetition, drift, experimentation, quits.`,`Then tasks if you need usability data. Then interview: open questions first ("walk me through what you did"), leading questions never.`,`Log behavior: choices, times, deaths, retries.`,`Synthesize: cluster observations, separate behavior from opinion, note surprises. Decide one or two changes. Test again.`],
  ai:{ yes:[`Draft observation protocols and interview guides.`,`Transcribe and code recordings and notes into behavior categories.`,`Cluster findings across testers and surface patterns and outliers.`,`Analyze telemetry and correlate with observed events.`],
       no:[`Interpret what a behavior means for the design without you. It lacks the context.`,`Decide what to change. That is the design decision.`,`Replace players. AI has never played your game as a human would.`] },
  prompts:[{l:'Observation protocol',p:`We are testing the hypothesis "[HYPOTHESIS]" with [N] players matching [PLAYER MODEL] for [MINUTES]. Design a silent observation protocol: what to log with timestamps (hesitations, repeats, drift, experiments, quits, speech), a task list if needed, and an interview guide of open, non-leading questions ordered from behavior to opinion. Include a coding scheme for the notes and a template for the results summary that separates behavior from self-report.`},
    {l:'Playtest synthesis',p:`Here are observer notes and interview transcripts from [N] playtests: [DATA]. Code every observation as behavior or self-report. Cluster behaviors by pattern and report frequency per cluster. Separate patterns (2 or more testers) from outliers, and list outliers separately with why they might matter. Identify contradictions between what players did and what they said. State what the evidence supports about the hypothesis "[HYPOTHESIS]" and what it does not. Do not recommend design changes.`}],
  verify:[`Did it treat one tester's statement as a finding?`,`Did it merge behavior and opinion?`,`Did it recommend changes when asked only to synthesize?`],
  test:[`This topic is the test. Questions to answer in every session: Do players understand the goal without explanation? Do they notice the meaningful choice? Do they make different choices? Do they understand why they succeeded or failed? Do they voluntarily repeat? Do they experiment? Do they develop strategies? Do they create their own goals? Where do they get bored, confused, or lose agency?`],
  rel:[['hypothesis-driven-design','Tests need a hypothesis.'],['iteration-and-evidence','Tests produce the evidence that drives iteration.'],['who-is-the-player','Recruiting is where the player model meets reality.'],['ai-for-playtest-analysis','AI helps analyze. Humans interpret.'],['playtest-view','The Playtest view has the question bank and hypothesis builder.']] });

T('iteration-and-evidence',{ d:'production', t:'Iteration on evidence', tag:'Change one important thing, test again. Iteration without evidence is wandering.',
  what:`The cycle of prototype, test, evidence, decision, repeated. The discipline is to change the fewest variables that could move the signal, so that the next test can attribute the result. Evidence includes behavior logs, observations, and telemetry, interpreted with context by humans.`,
  why:[`Iteration is how games get good. Nobody designs a great loop on paper.`,`Changing many things at once makes results unattributable. You learn nothing even when it improves.`,`AI makes iterations cheap, which is only useful if each iteration is informed by evidence. Fast wandering is still wandering.`],
  think:{ q:[`What did the last test show? What is the one change most likely to move the signal?`,`If the change helps, will I know why?`,`How many iterations without player contact have I done? More than two is a warning.`,`Am I iterating toward the core experience, or toward whatever the last tester said?`],
    trade:[`One change per iteration is slow and attributable. Many changes are fast and blind.`,`Reacting to every test overfits to individuals. Ignoring tests wastes them.`],
    traps:[`Iterating on opinion instead of behavior.`,`Endless iteration with AI without a playtest in between.`,`Losing the thread: no record of what was tried and what happened.`],
    good:[`A log of hypotheses, changes and results exists and is read.`,`Each iteration has a reason traceable to evidence.`],
    bad:[`The team cannot say why the current version is the way it is.`] },
  how:[`Keep an iteration log: hypothesis, change, test, result, decision.`,`After each test, choose one or two changes with the best expected effect on the signal.`,`Do not iterate more than twice without player contact.`,`Every few cycles, step back: are the changes converging on the core experience?`],
  ai:{ yes:[`Maintain and summarize the iteration log.`,`Propose the change most likely to move the signal, with reasoning.`,`Detect when iterations are wandering (no convergence, contradictory changes).`,`Implement the change fast.`],
       no:[`Choose the change. That is a judgment about what matters.`,`Substitute its own evaluation for a playtest.`] },
  prompts:[{l:'Next iteration',p:`Here is our iteration log so far: [LOG] and the latest playtest evidence: [EVIDENCE]. Which single change is most likely to move the signal "[SIGNAL]", and why? List 3 candidates with expected effect, risk of side effects on [OTHER SIGNALS], and implementation cost. Point out if the log shows we are oscillating or reacting to individual testers rather than patterns.`}],
  verify:[`Did it pick based on evidence in the log, or on general design lore?`,`Did it flag overfitting to one tester?`],
  test:[`Did the signal move after the change? Can you attribute it?`,`Are you converging: fewer, smaller changes over time?`],
  rel:[['hypothesis-driven-design','Each iteration starts with a hypothesis.'],['playtesting','Evidence comes from tests.'],['ai-loop','Iteration is the outer loop of the master workflow.'],['ai-failure-modes','Endless iteration without evidence is a named failure.']] });

T('vertical-slice-mvp',{ d:'production', t:'Vertical slice and MVP', tag:'A slice proves the experience at full quality. An MVP proves players want it. Know which you are making.',
  what:`A vertical slice is a small section of the game at shipping quality across all disciplines, made to prove the experience and the pipeline. A minimum viable product is the smallest version that delivers the core experience to real players. Richard Lemarchand's concentric development finishes the core to quality before layering secondary systems.`,
  why:[`Horizontal building (all systems at low quality) hides whether the experience works. The slice forces the question.`,`The slice reveals the true cost per unit of content, which is the only honest basis for scope.`,`An MVP in players' hands produces the evidence no internal test can.`],
  think:{ q:[`Does this slice contain the core loop at full quality, or the easy parts polished?`,`What does the slice teach about cost per level, per enemy, per minute?`,`What is the smallest thing players would play voluntarily?`,`What is deliberately not in the slice, and why?`],
    trade:[`Slicing early commits to a direction. Slicing late wastes horizontal work.`,`Early access as MVP yields real evidence and public judgment.`],
    traps:[`Slice as a marketing demo rather than a proof.`,`Polishing a slice of an unvalidated loop.`,`MVP that omits the thing the game is about.`],
    good:[`The slice answers "does the experience work at quality?" with a yes or no.`,`Cost data from the slice drives the scope plan.`],
    bad:[`The slice looks great and the team still argues about the loop.`] },
  how:[`Validate the loop in grey boxes first.`,`Pick the section that best represents the core experience. Build it to shipping quality across disciplines.`,`Measure cost per unit. Recompute scope.`,`Consider an MVP release or closed test for real player evidence.`],
  ai:{ yes:[`Estimate cost per unit from the slice and project scope.`,`Implement production tooling and pipelines.`,`Track and flag scope drift against the slice-derived plan.`],
       no:[`Decide the slice proves the experience. Players decide.`] },
  prompts:[{l:'Slice scope',p:`Our core experience is "[STATEMENT]" and our validated loop is [DESCRIPTION]. Propose the smallest vertical slice that would prove the experience at shipping quality: which section, which systems at full quality, what is explicitly excluded and why. List the cost-per-unit measurements the slice should produce and how they would be used to set total scope.`}],
  verify:[`Did it include the hard part of the experience in the slice, or the easy part?`],
  test:[`Do players describe the slice the way the core experience statement does?`,`Does the slice reveal cost data? Recompute scope with it.`],
  rel:[['prototyping','Prototype first, slice second.'],['scope-control','Slice data sets scope.'],['polish-when','The slice is where polish is first justified.']] });

T('risk-and-dependencies',{ d:'production', t:'Risk, dependencies and technical constraints', tag:'Test the riskiest assumption first. Everything downstream of it is a bet.',
  what:`Identifying what could sink the game (a loop that is not fun, a technology that does not scale, a content pipeline that costs too much, a platform certification), the order in which risks should be retired, and the dependencies between features that decide what can be validated when.`,
  why:[`Projects fail on the assumptions nobody tested, not the ones everyone worried about.`,`Dependencies decide the order of work. Building on an unvalidated dependency multiplies risk.`,`Technical constraints are design constraints. Discovering them late means redesign.`],
  think:{ q:[`What would have to be true for this game to work? Which of those have I tested?`,`What is the single riskiest assumption? What is the cheapest test?`,`Which features depend on which validated results?`,`What technical constraint could change the design? Have I hit it yet?`],
    trade:[`Retiring risk early costs time before visible progress.`,`Parallel work speeds output and multiplies rework if a dependency fails.`],
    traps:[`Testing the safe parts because they are satisfying to build.`,`Treating technology as someone else's risk.`,`Dependency chains where the fun is at the end.`],
    good:[`The risk list is short, ordered, and shrinks.`,`Prototypes target the top risk.`],
    bad:[`The fun is scheduled for a milestone eleven months out.`] },
  how:[`List what must be true. Rank by impact if false times uncertainty.`,`For the top three, define the cheapest test and run it.`,`Map feature dependencies. Schedule so that validated results unlock the work that depends on them.`,`Hit technical constraints early with stress tests.`],
  ai:{ yes:[`Build the dependency graph and risk register from documents.`,`Propose cheapest tests per risk.`,`Run technical stress tests and summarize limits.`],
       no:[`Rank risks by importance to the experience. That is judgment.`] },
  prompts:[{l:'Risk register',p:`Here is our design and plan: [DOCS]. List the assumptions that must be true for the game to work, grouped as experience, technical, production and market. Score each by impact if false and current uncertainty. For the top 5, propose the cheapest test and what result would retire the risk. Then draw the feature dependency graph and flag features currently scheduled before the results they depend on.`}],
  verify:[`Did it include experience risk ("the loop is not fun"), or only technical and production risk?`],
  test:[`Did the prototype target the top risk?`,`Has the risk list shrunk since last month?`],
  rel:[['prototyping','Prototypes retire risk.'],['scope-control','Dependencies order scope.'],['core-loop','The loop is usually the top experience risk.']] });

T('polish-when',{ d:'production', t:'When to polish', tag:'Polish amplifies validated experience. Polish before validation hides the truth and wastes the work.',
  what:`The production decision of when to spend on feel, art, audio and presentation quality. Polish is expensive, changes when the design changes, and makes a weak loop feel temporarily better. It belongs after the loop is voluntarily replayed and before players judge the whole.`,
  why:[`Polish on a loop that changes is thrown away.`,`Polish on a weak loop delays discovering the weakness.`,`But unpolished feel can hide a good loop from testers who cannot get past the friction. Feel basics (latency, clear feedback) are not polish. They are legibility.`],
  think:{ q:[`Is the loop voluntarily replayed in grey boxes? If not, do not polish.`,`Which polish is legibility (needed for tests) and which is emphasis (needed for shipping)?`,`What is the polish cost per unit and does the scope plan account for it?`,`Which polish opportunities are cheap and high impact?`],
    trade:[`Early polish motivates the team and misleads them.`,`Late polish is efficient and compresses the schedule.`],
    traps:[`Polishing to make a milestone demo look good.`,`Calling feedback and latency fixes "polish" and deferring them.`],
    good:[`Polish work starts on validated systems and is prioritized by impact.`],
    bad:[`Beautiful builds with an unresolved loop debate.`] },
  how:[`Separate legibility fixes (do now) from emphasis polish (do after validation).`,`After validation, list polish opportunities by impact per cost.`,`Polish in passes across the whole validated slice rather than deep on one part.`,`Re-test readability after each pass.`],
  ai:{ yes:[`Rank polish opportunities by impact per cost.`,`Implement feel systems with exposed tuning.`,`Flag polish work on unvalidated systems.`],
       no:[`Decide the loop is validated. Players do.`] },
  prompts:[{l:'Polish gate',p:`Here is our validation evidence per system: [EVIDENCE] and our proposed polish tasks: [TASKS]. Classify each task as legibility (needed for testing) or emphasis (post-validation). Flag emphasis tasks targeting systems without validation evidence. Rank the remaining by impact on the top 5 player actions per hour of work.`}],
  verify:[`Did it respect the validation gate, or rank everything?`],
  test:[`Is the loop replayed before polish? After polish, is readability preserved?`],
  rel:[['game-feel-and-juice','What polish does.'],['vertical-slice-mvp','The slice is the first place polish is justified.'],['ai-loop','Polish is step 11 of the master loop.']] });

/* ---------------- AI COLLABORATION ---------------- */
T('bottleneck-shift',{ d:'ai', t:'The bottleneck shift', tag:'AI generates possibilities cheaply. Humans decide what is worth making. A polished bad idea is still a bad game.',
  what:`The traditional workflow was: human thinks, human designs, human documents, human implements. The AI-era workflow is: human frames the problem, AI expands, searches and analyzes, human judges, AI prototypes and implements, players provide evidence, human decides, AI iterates. The bottleneck moves from production to judgment: taste, framing, prioritization, understanding players, recognizing fun, separating signal from noise, making tradeoffs, and knowing what not to build.`,
  why:[`When implementation was expensive, scarcity forced selection. Now selection must be deliberate or the game fills with mediocre content.`,`AI output is fluent and plausible by default, which makes bad ideas look finished.`,`The skills that now matter (framing, judgment, evidence) are the ones least practiced by teams used to spending their time producing.`],
  think:{ q:[`Where am I spending my time: producing, or judging and testing? The ratio should have flipped.`,`What did I decide today that AI could not have decided? If nothing, I delegated judgment.`,`What evidence from players informed today's decisions? If none, I am iterating in a vacuum.`,`What did I decide not to build today?`],
    trade:[`Delegating production frees judgment time and distances the designer from the material. Some insight comes only from making.`,`Fast iteration is powerful and can outrun the playtest cadence.`],
    traps:[`Using AI to produce more instead of to test more.`,`Treating fluency as quality.`,`Letting AI frame the problem and then choosing among its options.`,`Iterating with AI as a substitute for iterating with players.`],
    good:[`More prototypes, more playtests, fewer features than before.`,`Design documents are shorter and hypotheses are more precise.`],
    bad:[`The game has more content and the same core problems.`] },
  how:[`Frame before prompting: player, fantasy, current loop, constraints, evidence, known problems, the decision you need to make.`,`Delegate expansion, analysis, prototyping and implementation. Keep framing, judgment, tradeoffs and the final decision.`,`Insert a playtest between every major AI iteration cycle.`,`Track your not-list. Cheap production makes it the most important artifact you own.`],
  ai:{ yes:[`Expand the possibility space, analyze patterns, compare alternatives, find edge cases, build prototypes, write implementation code, simulate systems, create test matrices, summarize playtest data, challenge assumptions.`],
       no:[`Decide what is fun. Decide the game's identity. Decide which tradeoff matters most. Decide what the player should feel. Decide whether a mechanic deserves to exist.`] },
  prompts:[{l:'Framing before asking',p:`Before you propose anything, restate my problem in your own words and list the assumptions you would have to make to answer it. Here is the context: player [PLAYER], fantasy [FANTASY], current loop [LOOP], constraints [CONSTRAINTS], evidence so far [EVIDENCE], known problems [PROBLEMS], and the decision I need to make: [DECISION]. Tell me what is missing from this framing before you continue.`}],
  verify:[`Did the AI frame the problem, or did I?`,`What would I have decided differently without the AI, and why?`],
  test:[`Count prototypes and playtests per month before and after adopting AI. The ratio to features should rise.`],
  rel:[['ai-roles','Roles are how the human directs the AI.'],['responsibility-matrix','The matrix operationalizes the split.'],['ai-failure-modes','What happens when the split fails.'],['ai-loop','The master workflow is the bottleneck shift as a process.'],['scope-control','Cheap production makes scope control the hard problem.']] });

T('ai-roles',{ d:'ai', t:'AI as different design partners', tag:'Ask for a role, not for "ideas". Each role has a job, a time to use it, and a time to keep it away.',
  what:`Nine ways to cast the AI: brainstormer (expands the space), critic (attacks assumptions), systems designer (analyzes interactions), UX researcher (finds friction), prototype engineer (builds experiments), playtest analyst (finds behavioral patterns), content generator (creates variations after validation), project analyst (finds dependencies, risks, scope problems), devil's advocate (argues against the current design). Naming the role sets the stance, the output shape, and what the AI should refuse to do.`,
  why:[`An unrolled request produces the average of all stances: mild ideas, mild critique, mild everything.`,`Roles make verification easier: you know what a critic should have done and can check whether it did.`,`Roles keep the AI out of decisions: none of the nine is "decider".`],
  think:{ q:[`What do I need right now: more options, fewer options, a build, an analysis, or a challenge?`,`Which role would a good studio bring into this meeting?`,`Which role should I keep out? (Content generator before validation. Brainstormer when the problem is a decision.)`,`After the role's output, what is my job?`],
    trade:[`Sequencing roles (brainstorm, then critique, then analyze) is slower and far better than asking one prompt to do everything.`],
    traps:[`Asking the brainstormer to recommend.`,`Asking the critic after you have committed.`,`Asking the content generator before the system is validated.`,`Skipping the devil's advocate because the team agrees.`],
    good:[`Prompts start with a role and end with what the role must not do.`],
    bad:[`Prompts are "help me with combat".`] },
  how:[`Pick the role from the AI Workflow view. Read its use and do-not-use conditions.`,`Give the role full context (the prompting framework) and a task with an output shape.`,`Sequence: brainstormer, critic, systems designer, prototype engineer, playtest analyst, devil's advocate before commit.`,`Do the human job after each role: judge, choose, decide.`],
  ai:{ yes:[`Everything in the nine roles, when cast deliberately.`],
       no:[`Be the decider. No role decides identity, fun, or tradeoffs.`] },
  prompts:[{l:'Role sequence',p:`We are working on [PROBLEM]. Run these roles in sequence and label each section. 1. Brainstormer: 8 mechanically distinct options, no recommendation. 2. Critic: for each option, the assumption it depends on and the player behavior that would disprove it. 3. Systems designer: interactions of the top 3 (by your critique) with our existing systems [SYSTEMS]. 4. Devil's advocate: argue that we should build none of them and improve [EXISTING INTERACTION] instead. Stop. I will decide.`}],
  verify:[`Did each role stay in its lane? Did the brainstormer sneak in a recommendation?`,`Did the critic attack, or nod?`],
  test:[`The roles do not replace testing. They prepare it. Did the sequence produce a hypothesis you can test?`],
  rel:[['bottleneck-shift','Roles keep judgment human.'],['prompting-framework','Role is one term of the formula.'],['verifying-ai-output','Each role has its own verification questions.'],['ai-roles-view','The AI Workflow view has the interactive role cards.']] });

T('prompting-framework',{ d:'ai', t:'The prompting framework', tag:'CONTEXT + INTENT + CONSTRAINTS + EVIDENCE + ROLE + TASK + OUTPUT FORMAT + CRITIQUE.',
  what:`A structure for delegating design work: Context (player, fantasy, loop, systems), Intent (the experience you are after and the decision you need to make), Constraints (scope, platform, team, what is off the table), Evidence (playtest results, telemetry, known problems), Role (the stance), Task (the specific work: analyze, generate, compare, build), Output format (how you will consume it), Critique (ask the AI to attack its own output). The best prompt is rarely "give me ideas". It is "here is the situation, analyze the space, identify assumptions, generate alternatives, compare tradeoffs, propose the smallest experiments".`,
  why:[`AI output quality tracks input specificity. Vague prompts get genre averages.`,`Framing is the human's most valuable contribution. The framework forces you to do it.`,`Output format and critique turn a monologue into something you can verify and act on.`],
  think:{ q:[`Have I stated the decision I need to make? If not, the AI will make one for me or make none.`,`What evidence do I have? If none, the task should be a prototype or a test design, not a design.`,`How will I consume the output? A table? A ranked list? Code?`,`What do I want the AI not to do?`],
    trade:[`Long prompts cost time up front and save many rounds of correction.`,`Tight constraints produce relevant output and can exclude the surprising option. Loosen deliberately for brainstorming.`],
    traps:[`Context without intent: the AI describes instead of deciding what to analyze.`,`Task without output format: unusable prose.`,`No critique step: the output looks finished and is unexamined.`],
    good:[`Prompts are reusable with variables swapped.`,`Output can be verified against the constraints stated.`],
    bad:[`Every prompt is a new conversation from zero.`] },
  how:[`Use the Prompt Generator: fill the eight fields and copy.`,`Save prompts that worked as templates in the library with variables.`,`Always end with a critique instruction and a stop instruction ("do not recommend yet").`,`Follow with the verification questions.`],
  ai:{ yes:[`Draft or improve a prompt from a rough request, then tell you what context it is missing.`],
       no:[`Fill in the intent or evidence for you.`] },
  prompts:[{l:'The full formula',p:`CONTEXT: player [PLAYER], fantasy [FANTASY], core loop [LOOP]. Systems [SYSTEMS]. INTENT: we want players to feel [EMOTION] by [BEHAVIOR], the decision I must make is [DECISION]. CONSTRAINTS: [PLATFORM, SCOPE, TEAM, OFF-LIMITS]. EVIDENCE: [PLAYTEST RESULTS, TELEMETRY, KNOWN PROBLEMS]. ROLE: act as a skeptical [ROLE]. TASK: analyze the design space, identify the assumptions in the current design, generate [N] mechanically distinct alternatives, compare tradeoffs, and propose the smallest experiments that would distinguish between them. OUTPUT: a table with columns [COLUMNS], then a short list of experiments with observable signals. CRITIQUE: finally, attack your own output: what assumptions did you make, what could make each alternative fail, and what did you leave out? Do not recommend a final choice.`}],
  verify:[`Did the output respect every constraint? Check each.`,`Did it use the evidence, or ignore it?`,`Did the critique section actually find something?`],
  test:[`Prompts are not tested by players. The experiments they propose are.`],
  rel:[['ai-roles','Role is one term.'],['verifying-ai-output','What to do after the output.'],['prompt-library','Reusable templates built on the formula.'],['bottleneck-shift','Framing is the new bottleneck.']] });

T('verifying-ai-output',{ d:'ai', t:'Verifying AI output', tag:'Fluent is not correct. Ask what it assumed, what evidence it used, and what would prove it wrong.',
  what:`The discipline of interrogating AI output before acting on it: What assumptions are you making? What evidence supports this? What could make this fail? What player behavior would prove this wrong? Is this solving the actual problem or producing more content? Is this complexity necessary? What is the smallest prototype that tests this? What alternatives did we reject? What tradeoff are we making?`,
  why:[`AI output is confident by default. Confidence is not a signal.`,`Hallucinated best practices, invented data and plausible-sounding psychology are common and hard to spot in fluent prose.`,`Verification is where the human adds value: not by redoing the work, but by checking it against the problem, the evidence and the player.`],
  think:{ q:[`Which claims here are derived from what I provided, and which are imported from elsewhere?`,`Would this survive a skeptical senior designer's first question?`,`Does it solve the problem I stated, or a nearby easier one?`,`What did it not consider?`],
    trade:[`Deep verification is slow. Skipping it is how bad ideas get polished.`],
    traps:[`Verifying tone instead of content.`,`Accepting "studies show" without a source you can check.`,`Letting the AI verify itself in the same breath without new information.`],
    good:[`Every accepted output has a written note of what was checked.`,`Rejected outputs are as common as accepted ones.`],
    bad:[`Output is pasted into the design document unchanged.`] },
  how:[`Run the nine verification questions (in the checklist) on any output you might act on.`,`Check every factual claim you would rely on.`,`Restate the original problem and check the output answers it, not a neighbor.`,`For design proposals, insist on the smallest prototype and a kill criterion before building.`],
  ai:{ yes:[`Answer the verification questions about its own output when asked separately, and mark assumptions and inferences explicitly.`,`Generate counter-arguments to its own proposals.`],
       no:[`Be trusted because it sounds sure.`] },
  prompts:[{l:'Verification pass',p:`About your previous output: 1. List every assumption you made and mark each as given by me, inferred, or invented. 2. For each factual or "best practice" claim, state the source or say you have none. 3. What player behavior would prove the proposal wrong? 4. Is this solving the problem I stated, or a nearby one? Quote my problem. 5. Which complexity is necessary and which could be removed? 6. What is the smallest prototype that tests this, and what result would kill it? 7. What alternatives did you reject and why? 8. What tradeoff are we making?`}],
  verify:[`This topic is the verification.`],
  test:[`The prototype and kill criterion the verification produces are what you test.`],
  rel:[['ai-failure-modes','Failure modes are what verification catches.'],['prompting-framework','Critique is the last term of the formula.'],['hypothesis-driven-design','Verification ends in a testable hypothesis.'],['checklists-view','The AI-output verification checklist lives in Checklists.']] });

T('ai-failure-modes',{ d:'ai', t:'When AI makes your game worse', tag:'Generic design, feature inflation, false confidence, content spam, documentation theater. Each has a symptom, a cause, a detector and a fix.',
  what:`The characteristic ways AI collaboration degrades a game: generic design, feature inflation, overengineering, false confidence, hallucinated best practices, optimizing the wrong metric, copying genre conventions, excessive complexity, premature implementation, content spam, documentation theater, analysis paralysis, endless iteration without player evidence, treating AI output as authority. The full interactive catalogue with symptom, cause, detector and correction is in the AI Workflow view.`,
  why:[`These failures are systematic, not random: they follow from AI's strengths (fluency, volume, plausibility) meeting human weaknesses (deference, impatience, fear of deciding).`,`They are detectable early if you know the symptoms.`,`Each has a specific correction that is not "use AI less" but "use it differently".`],
  think:{ q:[`Is this output distinctive, or could it describe any game in the genre?`,`Did the feature list grow this week? Did the loop improve?`,`When did a player last touch the build?`,`Am I accepting this because it is right, or because it is done?`],
    trade:[`Guarding against every failure mode slows you down. The fix is cadence (regular playtests) rather than paranoia.`],
    traps:[`Blaming the tool for a workflow failure.`,`Fixing content spam by generating "better" content instead of validating the system.`],
    good:[`The team names failure modes when they see them.`],
    bad:[`The game is bigger every week and nobody can say why it is better.`] },
  how:[`Read the catalogue. Pick the three you are most prone to.`,`Add a detector for each to your weekly review (feature count, playtest count, distinctiveness check).`,`When detected, apply the correction from the catalogue and record it.`],
  ai:{ yes:[`Audit its own recent outputs for the failure modes when asked.`,`Compute detectors (feature growth, iteration count without tests) from your logs.`],
       no:[`Be the judge of whether the game is better. Players are.`] },
  prompts:[{l:'Self-audit',p:`Review the design proposals you produced in this conversation. For each, check: could it describe any game in the genre (generic)? Does it add rules without adding decisions (inflation)? Does it assert best practices without sources (hallucination)? Does it propose building before testing (premature implementation)? Does it generate content for an unvalidated system (spam)? Report honestly and propose the correction for each hit.`}],
  verify:[`Did the self-audit find anything? If it found nothing, be suspicious.`],
  test:[`The corrections all end in a playtest. Did one happen?`],
  rel:[['bottleneck-shift','Failure modes are the bottleneck shift ignored.'],['verifying-ai-output','Verification catches them.'],['scope-control','Inflation and spam are scope failures.'],['ai-failures-view','The interactive catalogue is in the AI Workflow view.']] });

T('responsibility-matrix',{ d:'ai', t:'Human vs AI responsibility', tag:'Primary, assist, shared. Decide who owns each task before the work starts, not after the output arrives.',
  what:`A matrix assigning each design task to a primary owner: human (identity, fun judgment, tradeoffs, what not to build), AI (alternatives, prototypes, content variations, data analysis), or shared (complexity analysis, playtest interpretation). The interactive matrix is in the AI Workflow view. The AI Delegation Planner lets you assign your own tasks.`,
  why:[`Ownership decided in advance prevents drift: without it, whoever produces the artifact owns the decision by default, and that is usually the AI.`,`The matrix makes "AI should not decide this" a rule rather than a feeling.`,`It also makes delegation safe: tasks marked AI-primary can be delegated confidently.`],
  think:{ q:[`Who owns this task? If I cannot say, I am about to let the output decide.`,`Is this a judgment (human), a production (AI), or an analysis (shared)?`,`Does this task require player evidence before anyone can own it?`],
    trade:[`Strict ownership is clear and can waste AI's ability to contribute to judgment tasks as an assistant.`],
    traps:[`Marking everything shared.`,`Letting AI-primary tasks quietly include decisions (a prototype that embeds a design choice nobody made).`],
    good:[`Every task in the plan has an owner and the decisions embedded in AI work are surfaced.`],
    bad:[`The design document was written by AI and nobody remembers deciding its contents.`] },
  how:[`For each task, use the AI Delegation Planner: Human, AI, Human + AI, or Player evidence required.`,`For AI-primary tasks, list the decisions embedded in the work and route them to a human.`,`Review the plan weekly. Ownership drifts.`],
  ai:{ yes:[`Suggest ownership for tasks based on the matrix, and flag hidden decisions in AI-primary work.`],
       no:[`Assign itself judgment tasks.`] },
  prompts:[{l:'Hidden decisions',p:`You are about to [TASK]. Before you do, list every design decision that doing this task will embed (defaults, structures, numbers, exclusions). For each, state the options and which you would pick and why, then stop and let me choose before you proceed.`}],
  verify:[`Did the AI surface the decisions embedded in its work, or make them silently?`],
  test:[`Not testable with players. Testable by audit of who decided what.`],
  rel:[['bottleneck-shift','The matrix is the bottleneck shift made explicit.'],['ai-roles','Roles are the AI side of the matrix.'],['matrix-view','The interactive matrix is in the AI Workflow view.']] });

T('ai-for-implementation',{ d:'ai', t:'AI for prototyping and implementation', tag:'The strongest use of AI: build the experiment fast, expose the knobs, log everything, throw it away.',
  what:`Using AI to write prototype and production code, tools, simulations and generators. The best results come from precise briefs (what to build, what to expose, what to log, what not to include), from insisting on instrumentation, and from treating prototypes as disposable. Production code needs the same review discipline as any code plus attention to the design decisions embedded in defaults.`,
  why:[`This is where AI most reliably saves time: prototypes in hours, simulations in minutes, tooling on demand.`,`Instrumented prototypes turn playtests into data.`,`Speed here is only valuable if it feeds more tests and more judgment, not more features.`],
  think:{ q:[`What question does this build answer? What must it log to answer it?`,`Which tuning values should be live so I can iterate during the test?`,`What must NOT be in this build? (Menus, saves, art, progression, unless the question needs them.)`,`What design decisions is the code making by default? Do I agree?`],
    trade:[`Fast builds encourage testing and encourage keeping code that should be thrown away.`],
    traps:[`Prototypes that become the codebase.`,`Builds without logging, so the test yields only opinions.`,`Accepting the AI's defaults (numbers, structures) as design decisions.`],
    good:[`A new prototype every few days, each with a hypothesis and logs.`],
    bad:[`One big build that keeps growing.`] },
  how:[`Write the brief: hypothesis, the minimal build, exposed tuning values, logged events, exclusions, and export format.`,`Ask for the embedded decisions before the build.`,`Run the test. Analyze the logs (AI can help).`,`Throw the prototype away or explicitly promote it with a refactor plan.`],
  ai:{ yes:[`Build prototypes, tools, simulations, generators, analysis scripts. Refactor promoted prototypes. Write tests.`],
       no:[`Decide what the prototype is for.`,`Choose defaults that are actually design decisions without surfacing them.`] },
  prompts:[{l:'Instrumented prototype brief',p:`Build a prototype in [ENGINE/HTML] that tests: [HYPOTHESIS]. Include only: [MECHANICS]. Exclude menus, saves, progression and art beyond shapes. Expose these values as live sliders: [VALUES]. Log with timestamps: every player input, every decision point and the option chosen, every failure and its cause, session start and end. Export logs as CSV. Before writing code, list the design decisions the code will embed (defaults, structures) and wait for my choices.`},
    {l:'Simulation',p:`Write a simulation of [SYSTEM] with these rules and numbers: [SPEC]. Model three player strategies: [STRATEGIES]. Run [N] iterations each and report: outcome distributions, the strategy that dominates and at what point, resource curves, and any runaway loop. Then vary [PARAMETER] across [RANGE] and report where the dominant strategy changes. Show me the assumptions the simulation makes about player behavior.`}],
  verify:[`Did it include anything not needed? Did it log what the hypothesis needs?`,`Which defaults did it choose, and would I have?`,`Does the simulation's player model resemble real players, or an optimizer?`],
  test:[`The prototype is the test. Did the logs answer the question?`],
  rel:[['prototyping','What prototypes are for.'],['procedural-content','Generators are implementation work.'],['economy-and-resources','Simulation is the main tool for economies.'],['responsibility-matrix','Prototype is AI-primary with human-owned decisions.']] });

T('ai-for-playtest-analysis',{ d:'ai', t:'AI for playtest analysis', tag:'AI finds patterns in notes, transcripts and telemetry. Humans supply the context and make the call.',
  what:`Using AI to transcribe, code, cluster and summarize playtest evidence: observer notes, recordings, interview transcripts, telemetry, replay logs. AI is fast and consistent at coding and pattern-finding. It lacks the context (what was intended, what the room felt like, what the tester's face did) that interpretation requires.`,
  why:[`Playtest data is voluminous and under-analyzed. Most teams act on impressions from the room.`,`Consistent coding across sessions reveals trends impressions miss.`,`AI analysis is only as good as the evidence you give it and the interpretation you apply afterward.`],
  think:{ q:[`What did I ask the test to answer? Give the AI the hypothesis.`,`What context does the AI lack? Add it: what was intended, what changed since last test, what I saw that is not in the notes.`,`Is it reporting behavior or paraphrasing opinions?`,`What did it call a pattern? Two testers is a hint, not a pattern.`],
    trade:[`AI coding is consistent and misses nuance. Human coding is nuanced and inconsistent. Use both.`],
    traps:[`Feeding transcripts without the hypothesis.`,`Accepting AI's interpretation of intent.`,`Letting it recommend design changes in the same pass as analysis.`],
    good:[`Analysis outputs separate behavior from self-report and patterns from outliers.`,`Decisions cite the analysis and add the human's context.`],
    bad:[`The AI summary becomes the design change list.`] },
  how:[`Provide hypothesis, protocol, notes, transcripts, logs and your own context.`,`Ask for coding and clustering, behavior separated from self-report, patterns separated from outliers, contradictions surfaced.`,`Interpret yourself. Then, in a separate step, ask for hypotheses about causes.`,`Decide. Record the decision and the evidence.`],
  ai:{ yes:[`Transcribe, code, cluster, count, correlate, summarize, surface contradictions and outliers.`],
       no:[`Interpret meaning without your context.`,`Recommend changes in the analysis pass.`] },
  prompts:[{l:'Telemetry and notes correlation',p:`Here are telemetry logs (events with timestamps per player) and observer notes for the same sessions: [DATA]. Hypothesis under test: [HYPOTHESIS]. Align notes to telemetry by time. Report: where observed hesitation or confusion coincides with specific game events, choice distributions at each decision point. Retry counts per challenge. Session-end events. Separate behavior from self-report. Mark patterns (present in 3 or more players) and outliers. Do not interpret causes or recommend changes.`}],
  verify:[`Did it stay in analysis, or slide into recommendations?`,`Did it count two testers as a pattern?`,`Did it use the hypothesis?`],
  test:[`Interpretation is verified by the next test: did the change you made on this analysis move the signal?`],
  rel:[['playtesting','What is being analyzed.'],['iteration-and-evidence','Analysis feeds the next iteration.'],['verifying-ai-output','Check the analysis before acting.']] });

T('ai-loop',{ d:'ai', t:'The AI-era development loop', tag:'Define, hypothesize, explore, critique, prototype, play, measure, interpret, decide, implement, polish, repeat.',
  what:`The master workflow: 1 Define (player, fantasy, experience). 2 Hypothesize (what must be true). 3 Explore (AI expands the space). 4 Critique (AI attacks assumptions). 5 Prototype (cheapest test). 6 Play (observe humans). 7 Measure (behavioral evidence). 8 Interpret (human plus AI). 9 Decide (keep, change, simplify, kill). 10 Implement (AI aggressively). 11 Polish (amplify validated experience). 12 Repeat. The interactive stepper in the AI Workflow view details each step's human role, AI role, output and exit criterion.`,
  why:[`It puts player evidence between exploration and commitment, which is the single discipline that prevents most AI-era failures.`,`It gives AI the steps where volume helps (explore, critique, prototype, implement) and humans the steps where judgment is the work (define, decide, interpret).`,`It is a loop: polish is not the end, it is the setup for the next hypothesis.`],
  think:{ q:[`Which step am I on? Which step did I skip to get here?`,`When did a player last touch the build (step 6)? If more than two cycles ago, stop and test.`,`Did I decide (step 9), or did I drift into implementing?`],
    trade:[`Running the whole loop is slow per cycle and fast per validated feature.`],
    traps:[`Skipping 5 through 8: explore, then implement.`,`Polishing (11) before deciding (9).`,`Defining (1) once and never revisiting.`],
    good:[`The team can name the current step and the last decision.`],
    bad:[`The loop is a line: define, implement, polish, ship.`] },
  how:[`Mark your current step in the AI Workflow view stepper. It persists.`,`Before moving on, check the exit criterion for the step.`,`Log each cycle: hypothesis, prototype, evidence, decision.`],
  ai:{ yes:[`Steps 3, 4, 5, 7 (collection), 8 (analysis), 10, and support in 11.`],
       no:[`Steps 1, 9, and the interpretation half of 8.`] },
  prompts:[{l:'Where are we?',p:`Here is our recent activity log: [LOG]. Map each item to a step of the loop (define, hypothesize, explore, critique, prototype, play, measure, interpret, decide, implement, polish). Which steps have we skipped in the last two cycles? When did a player last touch the build? What decision is pending that we have been implementing around instead of making?`}],
  verify:[`Did it identify skipped steps honestly?`],
  test:[`Step 6 is the test. Everything else exists to make it count.`],
  rel:[['hypothesis-driven-design','Step 2.'],['prototyping','Step 5.'],['playtesting','Step 6.'],['iteration-and-evidence','Steps 7 to 9.'],['polish-when','Step 11.'],['loop-view','The interactive stepper is in the AI Workflow view.']] });
